function employeePolicyText(p){return p?`${p.oldVersion}：${p.oldBefore}前；${p.newVersion}：${p.newFrom}起`:'固定版本'}
function renderPolicies(){const q=$('staffSearch').value.trim(),meta=campusStore.staffMeta();$('stafflist').innerHTML='<table><thead><tr><th>员工</th><th>当前 / 新版绩效</th><th>旧绩效版本</th><th>旧版适用签约日期</th><th>新版适用签约日期</th><th>最近更新</th><th>操作</th></tr></thead><tbody>'+Object.entries(state.staff).filter(([name])=>name.includes(q)).sort(([a],[b])=>a.localeCompare(b,'zh-CN')).map(([name,v])=>{const p=(state.staffRules||{})[name];return `<tr><td>${esc(name)}</td><td><select data-staff-name="${esc(name)}" aria-label="${esc(name)}的绩效版本">${staffVersions.map(version=>`<option ${v===version?'selected':''}>${version}</option>`).join('')}</select></td><td>${esc(p?.oldVersion||'—')}</td><td>${p?esc(p.oldBefore)+'前（不含当天）':'全部签约日期'}</td><td>${p?esc(p.newFrom)+'起（含当天）':'—'}</td><td>${esc(localDate(meta[name]?.updatedAt))}</td><td><button data-policy-name="${esc(name)}">设置签约日期规则</button> <button data-staff-history="${esc(name)}">查看变更</button></td></tr>`}).join('')+(Object.keys(state.staff).length?'':'<tr><td colspan="7">先添加员工，再为需要的员工设置新旧版本及适用日期。</td></tr>')+'</tbody></table>'}
const campusRenderBeforePolicy=renderCampus;renderCampus=function(){campusRenderBeforePolicy();renderPolicies()};$('staffSearch').oninput=renderCampus;
const refreshBeforePolicy=refreshCampusState;refreshCampusState=function(){$('policyPanel').classList.add('hidden');refreshBeforePolicy()};
const correctionBeforePolicy=openCorrection;openCorrection=function(id,mode){correctionBeforePolicy(id,mode);const entry=activeReview(),configured=!!state.staffRules?.[entry?.teacher];$('saveTeacherVersion').disabled=configured;$('saveTeacherVersion').title=configured?'此员工按签约日期分版，请在“员工与版本”中修改日期规则，避免用单个学生的版本覆盖员工规则。':''};
let policyEmployee='';
function openPolicy(name){policyEmployee=name;const p=(state.staffRules||{})[name];$('policyTitle').textContent=name+' · 按学生签约日期执行绩效';$('policyOldVersion').value=p?.oldVersion||state.staff[name];$('policyNewVersion').value=p?.newVersion||state.staff[name];$('policyOldBefore').value=p?.oldBefore||'';$('policyNewFrom').value=p?.newFrom||'';$('policyPanel').classList.remove('hidden');$('policyPanel').scrollIntoView({behavior:'smooth',block:'center'})}
const staffClickBeforePolicy=$('stafflist').onclick;$('stafflist').onclick=e=>{if(e.target.dataset.policyName){openPolicy(e.target.dataset.policyName);return}staffClickBeforePolicy(e);const name=e.target.dataset.staffHistory;if(name){const history=campusStore.staffMeta()[name]?.history||[];if(history.length)$('staffHistoryBody').innerHTML='<table><tr><th>更新时间</th><th>原版本</th><th>新版本</th><th>原日期规则</th><th>新日期规则</th></tr>'+[...history].reverse().map(h=>`<tr><td>${esc(localDate(h.at))}</td><td>${esc(h.from||'首次设置')}</td><td>${esc(h.to)}</td><td class="wrap">${esc(employeePolicyText(h.fromRule))}</td><td class="wrap">${esc(employeePolicyText(h.toRule))}</td></tr>`).join('')+'</table>'}};
function savePolicy(p){const name=policyEmployee;if(!Object.hasOwn(state.staff,name))return toast('未找到当前员工');if(p){const error=StaffVersionPolicy.validate(p);if(error)return toast(error)}const beforeRules={...(state.staffRules||{})},beforeVersion=state.staff[name];try{state.staffRules||={};if(p){state.staffRules[name]=p;state.staff[name]=p.newVersion}else delete state.staffRules[name];save();render();$('policyPanel').classList.add('hidden');toast('已保存签约日期规则。本期数据可点击“按员工名单重新匹配”更新，已人工核对的记录保留。')}catch(err){state.staffRules=beforeRules;state.staff[name]=beforeVersion;toast(err.message)}}
$('policyForm').onsubmit=e=>{e.preventDefault();savePolicy({oldVersion:$('policyOldVersion').value,oldBefore:$('policyOldBefore').value,newVersion:$('policyNewVersion').value,newFrom:$('policyNewFrom').value})};$('policyCancel').onclick=()=>$('policyPanel').classList.add('hidden');$('policyFixed').onclick=()=>{if(confirm('取消该员工的日期切换规则，所有签约日期统一使用当前版本“'+state.staff[policyEmployee]+'”？'))savePolicy(null)};
$('stafflist').onchange=e=>{const name=e.target.dataset.staffName;if(!name)return;const beforeVersion=state.staff[name],beforeRules=JSON.parse(JSON.stringify(state.staffRules||{}));try{state.staff[name]=e.target.value;if(state.staffRules?.[name])state.staffRules[name]={...state.staffRules[name],newVersion:e.target.value};save();render();toast('员工版本已更新；该员工若有日期规则，本次修改只更新新版，旧版保留')}catch(err){state.staff[name]=beforeVersion;state.staffRules=beforeRules;renderCampus();toast(err.message)}};
function applyManualPolicy(){if(editing)return;const name=$('teacher').value.trim(),selection=StaffVersionPolicy.resolve(name,$('studentSignDate').value,state.staff,state.staffRules||{});$('version').value=selection.version;populate();$('versionPolicyHint').textContent=selection.issue||selection.reason}
$('teacher').onchange=applyManualPolicy;$('studentSignDate').onchange=applyManualPolicy;
$('staffform').onsubmit=e=>{e.preventDefault();const name=$('staffname').value.trim();if(!name)return;const prevVersion=state.staff[name],prevRules={...(state.staffRules||{})};try{state.staff[name]=$('staffversion').value;if(state.staffRules?.[name])state.staffRules[name]={...state.staffRules[name],newVersion:state.staff[name]};save();render();$('staffname').value='';toast('已保存员工版本；已有日期规则的员工只更新新版，旧版及适用日期保留')}catch(err){if(prevVersion===undefined)delete state.staff[name];else state.staff[name]=prevVersion;state.staffRules=prevRules;toast(err.message)}};
$('staffExport').onclick=()=>download(JSON.stringify({schema:'campus-staff-v1',campus:campusStore.active().name,staff:state.staff,staffRules:state.staffRules||{},exportedAt:new Date().toISOString()},null,2),'员工版本名单.json','application/json');
$('staffCSV').onclick=()=>csv([['员工姓名','绩效版本','旧绩效版本','旧版签约截止日期（不含）','新绩效版本','新版生效签约日期（含）'],...Object.entries(state.staff).map(([name,v])=>{const p=state.staffRules?.[name];return [name,v,p?.oldVersion||'',p?.oldBefore||'',p?.newVersion||'',p?.newFrom||'']})],'员工版本名单.csv');
$('staffRestore').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;const d=JSON.parse(await file.text());if(d.schema!=='campus-staff-v1'||!d.staff||Array.isArray(d.staff)||Object.entries(d.staff).some(([n,v])=>!n.trim()||!staffVersions.includes(v)))throw Error('名单格式不正确');for(const [n,p]of Object.entries(d.staffRules||{})){const error=StaffVersionPolicy.validate(p);if(error||!Object.hasOwn(d.staff,n))throw Error(n+'的日期规则不完整')}if(!confirm('将员工版本和日期规则合并到本地？同名员工将更新，工资草稿保留。'))return;const beforeStaff={...state.staff},beforeRules={...(state.staffRules||{})};try{state.staff={...state.staff,...d.staff};state.staffRules={...beforeRules};if(Object.hasOwn(d,'staffRules'))for(const n of Object.keys(d.staff)){if(d.staffRules[n])state.staffRules[n]=d.staffRules[n];else delete state.staffRules[n]}save();render();toast('员工版本和日期规则已恢复')}catch(err){state.staff=beforeStaff;state.staffRules=beforeRules;throw err}}catch(err){toast('名单导入失败：'+err.message)}finally{e.target.value=''}};
renderCampus();
